      "verdict": "SUPPORT",
      "reason": "service.log 是检查对象，支持既有输入文件；原文没有要求修改它。",
      "sources": [
        {"quote": "检查 service.log", "clause_id": "c1", "occurrence": 0, "context_anchor": "请 PM 组织检查 service.log"}
      ]
    },
    {
      "candidate_id": "report",
