        {"quote": "形成 operation-review.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "“请 PM 组织”支持要求 PM 组织检查。组织是否同时支配形成文件存在协调范围歧义。",
